def run(self):
    fresh = self.repo.by_kyc_state(KYC_NEW)
    jobs = self._send(fresh)
    resolved, _ = self._collect()
    # members still without a result were dropped by the vendor (or are not answered yet);
    # sending them again is safe, the vendor judges a re-sent line normally
    jobs += self._send(self.repo.by_kyc_state(KYC_SENT))
    more, waiting = self._collect()
    resolved += more
    if resolved and self.on_resolved:
        self.on_resolved()
    return {"jobs": jobs, "sent": len(fresh), "resolved": resolved, "waiting": len(waiting)}

